package io.fireflysoftware.commons.ecm.core.signing;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import static org.junit.jupiter.api.Assertions.*;

class SigningPolicyCustodyRuntimeTest {
    @Test void samePrivateTraceAdmitsExactV3AppendWithOriginalTwoChecks(){var t=new SigningPolicyTraceRuntimeTest.Fixture();var calls=new AtomicInteger();assertNotNull(t.invoke((authority,permit)->t.runtime.withinPhase(permit,()->t.runtime.currentTrace(permit).flatMap(trace->{var evidence=new SigningAuditEvidenceV3(t.f.evidence(),trace);var event=evidence.event(permit,t.f.transport.clock.instant());return t.runtime.withinExpectedAppendV3(permit,evidence,event,()->t.runtime.requireCurrent(event).flatMap(first->t.runtime.requireCurrent(event)).map(second->{calls.incrementAndGet();return t.f.marker();}));}))).block(Duration.ofSeconds(2)));assertEquals(1,calls.get());assertEquals(2,t.calls.get());}
    @Test void equalCopiedTraceCannotCreateAppendCapability(){var t=new SigningPolicyTraceRuntimeTest.Fixture();var calls=new AtomicInteger();assertThrows(SecurityException.class,()->t.invoke((authority,permit)->t.runtime.withinPhase(permit,()->t.runtime.currentTrace(permit).flatMap(trace->{var copy=new SigningPolicyTraceV1(trace.phase(),trace.authorization(),trace.admission());var evidence=new SigningAuditEvidenceV3(t.f.evidence(),copy);return t.runtime.withinExpectedAppendV3(permit,evidence,evidence.event(permit,t.f.transport.clock.instant()),()->Mono.fromSupplier(()->{calls.incrementAndGet();return t.f.marker();}));}))).block(Duration.ofSeconds(2)));assertEquals(0,calls.get());}
    @Test void legacyExpectedAppendStillRefusesTheNewV3Digest(){var t=new SigningPolicyTraceRuntimeTest.Fixture();assertThrows(SecurityException.class,()->t.invoke((authority,permit)->t.runtime.withinPhase(permit,()->t.runtime.currentTrace(permit).flatMap(trace->{var business=t.f.evidence();var event=new SigningAuditEvidenceV3(business,trace).event(permit,t.f.transport.clock.instant());return t.runtime.withinExpectedAppend(permit,business,event,()->Mono.just(t.f.marker()));}))).block(Duration.ofSeconds(2)));}
    @Test void V3AppendCannotReenterOrExceedOriginalValidationCount(){var t=new SigningPolicyTraceRuntimeTest.Fixture();assertThrows(SecurityException.class,()->t.invoke((authority,permit)->t.runtime.withinPhase(permit,()->t.runtime.currentTrace(permit).flatMap(trace->{var evidence=new SigningAuditEvidenceV3(t.f.evidence(),trace);var event=evidence.event(permit,t.f.transport.clock.instant());return t.runtime.withinExpectedAppendV3(permit,evidence,event,()->t.runtime.requireCurrent(event).then(t.runtime.requireCurrent(event)).then(t.runtime.requireCurrent(event)).thenReturn(t.f.marker()));}))).block(Duration.ofSeconds(2)));assertEquals(2,t.calls.get());}
    @Test void legacyFactoryDoesNotSilentlyClaimPolicyCustodySupport(){SigningPreparationRuntimeFactory old=(account,content,envelopes)->Mono.error(new SigningIntegrationUnavailableException());assertThrows(SigningIntegrationUnavailableException.class,()->old.createPolicyCustody(null,null,null).block());}
}
